{
  "version": 1,
  "defaultSuite": "smoke",
  "suites": {
    "smoke": [
      { "action": "wait", "ms": 3000 },
      {
        "action": "assert",
        "expr": "!/加载失败|拿不到|接口返回/.test(document.body.innerText)",
        "matcher": "truthy",
        "note": "首页不能一上来就是错误态——真出错时这条会红，比截图上人眼看更早发现"
      },
      {
        "action": "assert",
        "expr": "document.querySelectorAll('[data-row-id]').length >= 5",
        "matcher": "truthy",
        "note": "推荐流至少渲染出 5 行（虚拟列表只渲可见区，所以不检查全量条数）"
      },
      {
        "action": "assert",
        "expr": "[...document.querySelectorAll('img')].some(i => i.src.startsWith('applet://localhost/image/'))",
        "matcher": "truthy",
        "note": "封面必须走 applet://image/ —— 裸 https 会被 CSP 静默拦成空白，这条是唯一能自动逮到的地方"
      },
      {
        "action": "assert",
        "expr": "/观看/.test(document.body.innerText)",
        "matcher": "truthy",
        "note": "播放量格式化生效（formatCount）"
      },
      {
        "action": "eval",
        "expr": "(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === '排行榜'); if (!b) throw new Error('排行榜 segment not found'); b.click(); return 'ok' })()"
      },
      { "action": "wait", "ms": 2500 },
      {
        "action": "assert",
        "expr": "document.querySelectorAll('[data-row-id]').length >= 5",
        "matcher": "truthy",
        "note": "切到排行榜后仍有内容（排行榜走的是另一个免签端点）"
      },
      {
        "action": "eval",
        "expr": "(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === '搜索'); if (!b) throw new Error('搜索 tab not found'); b.click(); return 'ok' })()"
      },
      { "action": "wait", "ms": 1500 },
      {
        "action": "eval",
        "expr": "(() => { const i = document.querySelector('input'); if (!i) throw new Error('search input not found'); const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set; setter.call(i, '编程'); i.dispatchEvent(new Event('input', { bubbles: true })); const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === '搜索'); b.click(); return 'ok' })()",
        "note": "受控 input 必须用原生 setter 再派发 input 事件，直接改 .value 不会触发 React 的 onChange"
      },
      { "action": "wait", "ms": 3500 },
      {
        "action": "assert",
        "expr": "/视频/.test(document.body.innerText) && document.querySelectorAll('[data-row-id]').length >= 3",
        "matcher": "truthy",
        "note": "搜索出结果 —— 这条同时验证了 WBI 签名是对的（签错会回 -403，结果为空）"
      },
      {
        "action": "eval",
        "expr": "(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === '我的'); if (!b) throw new Error('我的 tab not found'); b.click(); return 'ok' })()"
      },
      { "action": "wait", "ms": 2500 },
      {
        "action": "eval",
        "expr": "(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === '扫码登录'); if (!b) throw new Error('登录按钮未找到'); b.click(); return 'ok' })()"
      },
      { "action": "wait", "ms": 5000 },
      {
        "action": "assert",
        "expr": "[...document.querySelectorAll('img')].some(i => i.src.startsWith('applet://localhost/qr/'))",
        "matcher": "truthy",
        "note": "二维码画出来了。这条钉的是一个静默失败：登录接口在 passport.bilibili.com 而不是 api.bilibili.com，写错域名会拿到 HTTP 404 的 HTML 页（不是 JSON 错误码），报错信息指向不明"
      },
      {
        "action": "assert",
        "expr": "!/拿不到二维码/.test(document.body.innerText)",
        "matcher": "truthy",
        "note": "同上的反向断言：出错时页面会显示「拿不到二维码」"
      }
    ]
  }
}

// 哔哩哔哩（com.aibox.bilibili）—— 用 B 站 Web API + 原生外壳复刻移动端观感。
//
// 根职责：主题注入 → 接宿主底部 Tab（**声明在 manifest.scene.tabBar，不自绘**）
// → 用原生页栈推详情页 → 渲染当前 Tab。
//
// ## 这个应用为什么不是「套壳网页」
//
// 容器根本不允许套壳：WebView 只放行 `applet://`，也不能 iframe。所以每一屏都是原生外壳 + 自绘内容：
//  · 底部 Tab / 转场 —— 宿主的真原生控件；
//  · 长列表 —— `aibox/ui` 的虚拟列表（排行榜一次 100 条带封面，全量渲染必掉帧）；
//  · 长按菜单 —— 真 `UIContextMenuInteraction`（`useListGestures` 把行矩形喂给宿主）；
//  · 封面 —— `applet://image/` 走宿主两级图片缓存，不是裸 `<img>`（CSP 会拦）；
//  · 播放 —— 遥控宿主 AVPlayer，拿到全屏、画中画、锁屏卡片、后台播放。

import React from 'react'
import { useSubpageStack } from 'aibox/ui'
import FeedPage from './components/FeedPage.jsx'
import SearchPage from './components/SearchPage.jsx'
import MinePage from './components/MinePage.jsx'
import DetailPage from './components/DetailPage.jsx'
import { THEME_CSS, C } from './components/theme.js'
import { registerActions } from './lib/actions.js'

// 对外提供的 3 个 AI 动作（search / trending / play）。**模块求值期就注册**：
// 无头执行时页面不挂载任何组件，等 React 副作用就来不及了。
registerActions()

const bridge = () => (typeof window !== 'undefined' ? window.aibox : undefined)

/** 主题：CSS 变量注入 + 跟随系统深浅色。 */
function useTheme() {
  React.useEffect(() => {
    if (!document.getElementById('__bl_css__')) {
      const style = document.createElement('style')
      style.id = '__bl_css__'
      style.textContent = THEME_CSS
      document.head.appendChild(style)
    }
    const query = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null
    const apply = () => {
      document.documentElement.setAttribute(
        'data-prefers-color-scheme', query && query.matches ? 'dark' : 'light')
    }
    apply()
    query?.addEventListener?.('change', apply)
    return () => query?.removeEventListener?.('change', apply)
  }, [])
}

const TABS = [
  { id: 'feed', label: '首页' },
  { id: 'search', label: '搜索' },
  { id: 'mine', label: '我的' },
]

/**
 * 底部 Tab。身份在 manifest 里声明（宿主渲染真原生 TabBar），这里只接选中事件。
 *
 * 宿主没渲染出来时（surface 不支持 / 老宿主）回落到自绘条——**永远不能只有原生一条路**，
 * 否则在不支持的表面上整个应用就没法切页了。
 */
function useTabs(initial) {
  const [tab, setTab] = React.useState(initial)
  const [native, setNative] = React.useState(false)

  React.useEffect(() => {
    const api = bridge()
    if (!api?.tabs) return undefined
    let off
    ;(async () => {
      try {
        const state = await api.tabs.getState?.()
        setNative(!!state?.rendered)
        if (state?.selected) setTab(state.selected)
      } catch { setNative(false) }
      try {
        // 事件名是 'changed'，回调收的是整个 State（不是 {id}）——
        // `rendered` 也在里面，所以呈现表面变化（page → sheet）时自绘条能跟着切回来。
        off = api.tabs.on?.('changed', (state) => {
          if (state?.selected) setTab(state.selected)
          setNative(!!state?.rendered)
        })
      } catch { /* 没有事件面就只靠自绘条 */ }
    })()
    return () => { try { off?.() } catch { /* 已卸载 */ } }
  }, [initial])

  const select = React.useCallback((id) => {
    setTab(id)
    // 桥方法回的是 **Promise**，同步 try/catch 抓不住它的 rejection——那会变成
    // 「Unhandled promise rejection」污染 console。桥在能力不可用时是 reject 而不是 throw
    // （无头运行、sheet/card 表面上 tabs 都会拒），所以 `.catch` 是必需的，不是防御性冗余。
    try { bridge()?.tabs?.select?.(id)?.catch?.(() => {}) } catch { /* 连命名空间都没有 */ }
  }, [])

  return { tab, native, select }
}

/** 自绘底部条 —— 只在宿主没渲染原生 TabBar 时出现。 */
function FallbackTabBar({ value, onChange }) {
  return (
    <div style={{
      display: 'flex', borderTop: `1px solid ${C.line}`, background: C.bg,
      paddingBottom: 'env(safe-area-inset-bottom)', flexShrink: 0,
    }}>
      {TABS.map((item) => (
        <button
          key={item.id}
          type="button"
          onClick={() => onChange(item.id)}
          style={{
            flex: 1, border: 'none', background: 'transparent', padding: '10px 0',
            fontSize: 12, color: value === item.id ? C.brand : C.faint,
            fontWeight: value === item.id ? 600 : 400,
          }}
        >
          {item.label}
        </button>
      ))}
    </div>
  )
}

export default function App() {
  useTheme()
  const tabs = useTabs('feed')
  // 详情页走原生页栈：推入动画、边缘返回手势、顶栏标题全由宿主给。
  const stack = useSubpageStack({
    pathFor: (route) => `#/video/${route.bvid}`,
    titleFor: (route) => route.title || '视频',
  })

  const openVideo = React.useCallback((video) => {
    stack.push({ bvid: video.bvid, title: video.title })
  }, [stack])

  let body
  if (stack.route) {
    body = <DetailPage bvid={stack.route.bvid} onOpen={openVideo} />
  } else if (tabs.tab === 'search') {
    body = <SearchPage onOpen={openVideo} />
  } else if (tabs.tab === 'mine') {
    body = <MinePage onOpen={openVideo} />
  } else {
    body = <FeedPage onOpen={openVideo} />
  }

  return (
    <div style={{
      height: '100vh', display: 'flex', flexDirection: 'column',
      background: C.bg, color: C.text, overflow: 'hidden',
    }}>
      <div style={{ flex: 1, minHeight: 0 }}>{body}</div>
      {/* 详情页在页栈里时不显示 Tab 条（原生 TabBar 由宿主自己处理显隐） */}
      {!tabs.native && !stack.route ? (
        <FallbackTabBar value={tabs.tab} onChange={tabs.select} />
      ) : null}
    </div>
  )
}

// 视频详情页：播放 + 简介 + 分P/合集 + 相关推荐。
//
// ## 播放这条链路的三个关键决定
//
// 1. **不在页面里放 `<video>`。** secure CSP 的 `media-src` 不含 https，放了就是黑屏；
//    退一步就算开 loose 模式，WebView 的媒体一退后台就停、锁屏没有卡片、没有画中画。
//    所以走 `aibox.video.play` 遥控宿主的 AVPlayer（framework-capabilities §3.6 的裁决）。
// 2. **取流用 `fnval=1`（MP4）不是 DASH。** DASH 是音视频分离流，AVPlayer 放不了。
// 3. **续播位置存本地。** 宿主的播放器不知道「这是哪个视频的第几次观看」，
//    所以由本应用按 bvid+cid 记进度，起播时传 `resumeFrom`。

import React from 'react'
import { EmptyState, PrimaryButton, Spinner, StatItem } from './primitives.jsx'
import VideoCard from './VideoCard.jsx'
import { C, RADIUS, SPACE } from './theme.js'
import * as api from '../lib/api.js'
import {
  closeStage, copyText, haptic, imageURL, loadPref, onVideoProgress, openInBrowser,
  openStage, playVideo, savePref, share, toast, videoReadiness,
} from '../lib/host.js'
import { formatCount, formatDate, formatDuration } from '../lib/format.js'

const PROGRESS_KEY = 'watch-progress'

export default function DetailPage({ bvid, onOpen }) {
  const [detail, setDetail] = React.useState(null)
  const [state, setState] = React.useState('loading')
  const [error, setError] = React.useState('')
  const [relatedList, setRelated] = React.useState([])
  const [activeCid, setActiveCid] = React.useState(0)
  // `null` = 还没探测出来。**别用 true 当初值**：那会让页面先显示「能播」再跳成「不能播」。
  const [videoState, setVideoState] = React.useState(null)
  const playable = videoState?.ok !== false
  const [busy, setBusy] = React.useState(false)
  // 舞台开着时，视频由**宿主**画在页面顶部，页面自己那块封面就该让位——
  // 否则用户会同时看到「上面在放的视频」和「下面一张静止封面」。
  const [stageOn, setStageOn] = React.useState(false)
  const [descOpen, setDescOpen] = React.useState(false)
  const [progress, setProgress] = React.useState(null)

  React.useEffect(() => {
    let alive = true
    setState('loading')
    ;(async () => {
      try {
        const data = await api.videoDetail(bvid)
        if (!alive) return
        setDetail(data)
        setActiveCid(data.cid)
        setState('ready')
        api.related(bvid).then((list) => { if (alive) setRelated(list) })
      } catch (err) {
        if (!alive) return
        setError(String(err?.message || err))
        setState('error')
      }
    })()
    videoReadiness().then((s) => { if (alive) setVideoState(s) })
    return () => { alive = false }
  }, [bvid])

  // 订阅播放进度。三处刻意的节流——事件是 ~2Hz，而这一页下面挂着 20 条相关推荐：
  //
  //  · **按整秒去重再 setState**：进度条精度只到像素，亚秒级更新看不出差别，
  //    却会让整页每秒重渲两次（播放时用户其实在原生全屏播放器里，这些重渲全是白烧）。
  //  · **续播位置只记在 ref 里**，不是每帧都读写 storage —— 那是每秒两个桥往返。
  //  · 真正落盘放在卸载时（下面那个 effect）。
  //
  // 只认 `mine`：用户切去看别的视频时，不能把不相干的进度写到这条记录上。
  const pendingProgress = React.useRef(null)
  React.useEffect(() => {
    let lastWholeSecond = -1
    const off = onVideoProgress((snapshot) => {
      if (!snapshot?.mine) return
      if (snapshot.currentTime > 5 && snapshot.duration > 0) {
        const ratio = snapshot.currentTime / snapshot.duration
        // 快看完了就不记了——否则下次进来会从片尾开始
        pendingProgress.current = {
          key: `${bvid}:${activeCid}`,
          value: ratio > 0.95 ? 0 : Math.floor(snapshot.currentTime),
        }
      }
      const whole = Math.floor(snapshot.currentTime)
      if (whole === lastWholeSecond) return
      lastWholeSecond = whole
      setProgress(snapshot)
    })
    return off
  }, [bvid, activeCid])

  // 续播位置落盘：离开这一页时写一次。读-改-写要合并进已有的表，不能整表覆盖
  // （否则看第二个视频就会把第一个的进度抹掉）。
  React.useEffect(() => () => {
    const pending = pendingProgress.current
    if (!pending) return
    loadPref(PROGRESS_KEY, {})
      .then((all) => savePref(PROGRESS_KEY, { ...(all || {}), [pending.key]: pending.value }))
      .catch(() => { /* 存不住续播位置不值得打扰用户，也不该变成未处理拒绝 */ })
  }, [])

  // 离开这一页就收起视频区（不停播——转画中画或后台听声都是用户可能想要的）。
  React.useEffect(() => () => { closeStage() }, [])

  const play = React.useCallback(async (cid) => {
    if (!detail || busy) return
    setBusy(true)
    haptic('medium')
    try {
      // **先开舞台再播**：舞台开着时宿主把播放器嵌在页面顶部（保持竖屏、内容照常滚），
      // 否则会接管整屏并转横屏。开舞台是幂等的，重复调只更新参数。
      const stage = await openStage()
      setStageOn(!!stage?.rendered)
      const targetCid = cid || activeCid || detail.cid
      const stream = await api.playURL(bvid, targetCid)
      const saved = await loadPref(PROGRESS_KEY, {})
      const resumeFrom = Number(saved?.[`${bvid}:${targetCid}`]) || 0
      const part = detail.pages.find((p) => p.cid === targetCid)
      await playVideo({
        url: stream.url,
        title: part && detail.pages.length > 1 ? `${detail.title} · ${part.title}` : detail.title,
        resumeFrom,
      })
      setActiveCid(targetCid)
    } catch (err) {
      toast(`播放失败：${err?.message || err}`)
    } finally {
      setBusy(false)
    }
  }, [detail, bvid, activeCid, busy])

  if (state === 'loading') return <Spinner />
  if (state === 'error') {
    return <EmptyState title="打不开这个视频" detail={error} actionLabel="用浏览器打开"
      onAction={() => openInBrowser(`https://www.bilibili.com/video/${bvid}`)} />
  }

  const url = `https://www.bilibili.com/video/${bvid}`

  return (
    <div className="bl-scroll" style={{ height: '100%', overflowY: 'auto', background: C.bg }}>
      {/* 封面 + 播放键。舞台开着时整块隐藏——真正的画面在宿主画的视频区里。 */}
      {stageOn ? null : (
      <div
        onClick={() => playable && play()}
        style={{
          position: 'relative', width: '100%', aspectRatio: '16 / 9',
          background: C.surface, overflow: 'hidden',
        }}
      >
        {detail.cover ? (
          <img src={imageURL(detail.cover, 400)} alt=""
            style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
        ) : null}
        <div style={{
          position: 'absolute', inset: 0, display: 'flex',
          alignItems: 'center', justifyContent: 'center',
          background: 'rgba(0,0,0,0.25)',
        }}>
          <div style={{
            width: 58, height: 58, borderRadius: 29,
            background: 'rgba(0,0,0,0.5)', color: '#fff',
            display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 24,
          }}>
            {busy ? '···' : '▶'}
          </div>
        </div>
        {progress?.mine && progress.duration > 0 ? (
          <div style={{
            position: 'absolute', left: 0, bottom: 0, height: 3,
            width: `${Math.min(100, (progress.currentTime / progress.duration) * 100)}%`,
            background: C.brand,
          }} />
        ) : null}
      </div>
      )}

      {videoState && !videoState.ok ? (
        <div style={{ padding: SPACE.s3, background: C.brandDim, fontSize: 13, color: C.sub, lineHeight: 1.6 }}>
          {videoState.reason === 'noBridge'
            ? '这个 App 版本还没有视频播放桥（aibox.video）。需要重新构建安装 App 本体，'
              + '换小应用版本没用。'
            : '这个 App 构建没有链入视频播放器模块（MODULE_VIDEOPLAYER），播不了。'}
          <br />
          只能先用浏览器打开。
        </div>
      ) : null}

      <div style={{ padding: SPACE.s4 }}>
        <div style={{ fontSize: 17, fontWeight: 600, color: C.text, lineHeight: 1.4 }}>
          {detail.title}
        </div>
        <div style={{ fontSize: 12, color: C.faint, marginTop: SPACE.s2 }}>
          {formatCount(detail.play)}观看 · {formatDate(detail.pubdate)}
        </div>

        {/* UP 主 */}
        <div
          className="bl-press"
          onClick={() => openInBrowser(`https://space.bilibili.com/${detail.mid}`)}
          style={{ display: 'flex', alignItems: 'center', gap: SPACE.s2, marginTop: SPACE.s4 }}
        >
          {detail.avatar ? (
            <img src={imageURL(detail.avatar, 36)} alt=""
              style={{ width: 36, height: 36, borderRadius: 18, objectFit: 'cover', background: C.surface }} />
          ) : null}
          <div style={{ fontSize: 14, color: C.text }}>{detail.author}</div>
        </div>

        {/* 统计 */}
        <div style={{
          display: 'flex', marginTop: SPACE.s4, padding: `${SPACE.s3}px 0`,
          borderTop: `1px solid ${C.line}`, borderBottom: `1px solid ${C.line}`,
        }}>
          <StatItem label="点赞" value={formatCount(detail.like)} />
          <StatItem label="投币" value={formatCount(detail.coin)} />
          <StatItem label="收藏" value={formatCount(detail.favorite)} />
          <StatItem label="评论" value={formatCount(detail.reply)} />
        </div>

        {/* 简介：默认折叠，长简介会把整页推得很长 */}
        {detail.desc ? (
          <div
            onClick={() => setDescOpen((v) => !v)}
            style={{
              marginTop: SPACE.s3, fontSize: 13, color: C.sub, lineHeight: 1.6,
              whiteSpace: 'pre-wrap', wordBreak: 'break-word',
              maxHeight: descOpen ? 'none' : 60, overflow: 'hidden',
            }}
          >
            {detail.desc}
          </div>
        ) : null}

        <div style={{ display: 'flex', gap: SPACE.s2, marginTop: SPACE.s4 }}>
          <PrimaryButton onClick={() => play()} disabled={!playable || busy}>
            {busy ? '正在准备…' : '播放'}
          </PrimaryButton>
          <button
            type="button"
            onClick={async () => { await copyText(url); toast('链接已复制') }}
            style={{
              border: `1px solid ${C.line}`, background: 'transparent', color: C.sub,
              borderRadius: RADIUS.md, padding: `0 ${SPACE.s4}px`, fontSize: 14, flexShrink: 0,
            }}
          >
            复制
          </button>
          <button
            type="button"
            onClick={() => share(detail.title, url)}
            style={{
              border: `1px solid ${C.line}`, background: 'transparent', color: C.sub,
              borderRadius: RADIUS.md, padding: `0 ${SPACE.s4}px`, fontSize: 14, flexShrink: 0,
            }}
          >
            分享
          </button>
        </div>
      </div>

      {/* 分P / 合集 */}
      {detail.pages.length > 1 ? (
        <div style={{ paddingBottom: SPACE.s3 }}>
          <div style={{ padding: `0 ${SPACE.s4}px ${SPACE.s2}px`, fontSize: 13, fontWeight: 600, color: C.sub }}>
            选集（{detail.pages.length}）
          </div>
          <div className="bl-scroll" style={{ display: 'flex', gap: SPACE.s2, overflowX: 'auto', padding: `0 ${SPACE.s4}px` }}>
            {detail.pages.map((part) => (
              <button
                key={part.cid}
                type="button"
                onClick={() => play(part.cid)}
                style={{
                  flexShrink: 0, maxWidth: 160, textAlign: 'left',
                  border: 'none', borderRadius: RADIUS.md, padding: SPACE.s2,
                  background: part.cid === activeCid ? C.brandDim : C.surface,
                  color: part.cid === activeCid ? C.brand : C.text, fontSize: 12,
                }}
              >
                <div style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  P{part.page} {part.title}
                </div>
                <div style={{ color: C.faint, marginTop: 2 }}>{formatDuration(part.duration)}</div>
              </button>
            ))}
          </div>
        </div>
      ) : null}

      {/* 相关推荐。这里刻意不用虚拟列表：最多 40 条且在滚动容器末尾，
          再套一层虚拟滚动反而要处理嵌套滚动，得不偿失。 */}
      {relatedList.length ? (
        <div style={{ borderTop: `8px solid ${C.surface}`, paddingTop: SPACE.s2 }}>
          <div style={{ padding: `${SPACE.s2}px ${SPACE.s4}px`, fontSize: 13, fontWeight: 600, color: C.sub }}>
            相关推荐
          </div>
          {relatedList.slice(0, 20).map((video) => (
            <VideoCard key={video.bvid} video={video} onOpen={onOpen} />
          ))}
        </div>
      ) : null}
      <div style={{ height: SPACE.s6 }} />
    </div>
  )
}

// 首页：推荐 / 热门 / 排行 三段共用一条虚拟列表。
//
// 用 `aibox/ui` 的 VirtualList 而不是自己 map：排行榜一次回 100 条带封面，
// 全量渲染 ≈ 1000+ DOM 节点，滚动必掉帧。它同时负责把可见行矩形喂给原生手势层
// （`useListGestures`），长按菜单才能落在正确的行上。

import React from 'react'
import { VirtualList, useListGestures } from 'aibox/ui'
import VideoCard, { CARD_HEIGHT } from './VideoCard.jsx'
import { Segmented, Spinner, EmptyState } from './primitives.jsx'
import { C, SPACE } from './theme.js'
import * as api from '../lib/api.js'
import { copyText, haptic, openInBrowser, share, toast } from '../lib/host.js'

const SOURCES = [
  { id: 'recommend', label: '推荐' },
  { id: 'popular', label: '热门' },
  { id: 'ranking', label: '排行榜' },
]

/** 长按菜单。身份是静态的，可用性按行覆盖——这条纪律与宿主 `aibox.menu` 一致。 */
const ROW_ACTIONS = [
  { id: 'share', title: '分享', icon: 'square.and.arrow.up' },
  { id: 'copy', title: '复制链接', icon: 'link' },
  { id: 'web', title: '用浏览器打开', icon: 'safari' },
]

export default function FeedPage({ onOpen }) {
  const [source, setSource] = React.useState('recommend')
  const [items, setItems] = React.useState([])
  const [state, setState] = React.useState('loading')   // loading | ready | error
  const [error, setError] = React.useState('')
  // 权限没开与网络挂了是两种错：前者「重试」按钮点一万次也没用，得让用户去能力中心。
  const [needsPermission, setNeedsPermission] = React.useState(false)
  const freshIdx = React.useRef(1)

  const load = React.useCallback(async (kind, append = false) => {
    if (!append) { setState('loading'); setError('') }
    try {
      let next = []
      if (kind === 'recommend') {
        next = await api.recommend(append ? (freshIdx.current += 1) : (freshIdx.current = 1))
      } else if (kind === 'popular') {
        next = await api.popular(1)
      } else {
        next = await api.ranking(0)
      }
      setItems((prev) => {
        if (!append) return next
        // 推荐流会重复推同一条，按 bvid 去重，否则 VirtualList 的 key 会撞。
        const seen = new Set(prev.map((v) => v.bvid))
        return prev.concat(next.filter((v) => !seen.has(v.bvid)))
      })
      setState('ready')
    } catch (err) {
      // 追加失败不该把已有列表清空——用户正在看的东西不能因为下一页挂了就消失。
      if (append) { toast('没有更多了'); return }
      setNeedsPermission(!!err?.permission)
      setError(String(err?.message || err))
      setState('error')
    }
  }, [])

  React.useEffect(() => { load(source) }, [source, load])

  const handleAction = React.useCallback(async ({ rowId, actionId }) => {
    const video = items.find((v) => v.bvid === rowId)
    if (!video) return
    const url = `https://www.bilibili.com/video/${video.bvid}`
    haptic('light')
    if (actionId === 'share') await share(video.title, url)
    else if (actionId === 'copy') { await copyText(url); toast('链接已复制') }
    else if (actionId === 'web') await openInBrowser(url)
  }, [items])

  // 原生长按菜单。宿主不支持时 rendered=false，此时不装降级件——
  // 分享/复制在详情页都有入口，列表上少一个长按菜单不构成功能缺失。
  const gestures = useListGestures('feed', {
    contextMenu: ROW_ACTIONS,
    onAction: handleAction,
  })

  const header = (
    <Segmented items={SOURCES} value={source} onChange={setSource} />
  )

  if (state === 'error') {
    return (
      <div style={{ height: '100%', background: C.bg }}>
        {header}
        <EmptyState
          title={needsPermission ? '还没有联网权限' : '加载失败'}
          detail={error}
          actionLabel={needsPermission ? '我已开启，重新加载' : '重试'}
          onAction={() => load(source)}
        />
      </div>
    )
  }

  return (
    <VirtualList
      className="bl-scroll"
      style={{ height: '100%', background: C.bg }}
      regionId="feed"
      items={items}
      keyExtractor={(v) => v.bvid}
      estimatedRowHeight={CARD_HEIGHT}
      restoreKey={`feed:${source}`}
      header={header}
      empty={state === 'loading' ? <Spinner /> : <EmptyState title="这里还没有内容" />}
      footer={<div style={{ height: SPACE.s6 }} />}
      onVisibleRowsChange={gestures.onVisibleRowsChange}
      onEndReached={() => { if (source === 'recommend' && state === 'ready') load('recommend', true) }}
      renderRow={(video) => <VideoCard video={video} onOpen={onOpen} />}
    />
  )
}

// 「我的」：扫码登录 + 登录后的观看历史。
//
// ## 登录这条链路的形状
//
// 1. `qrcode/generate` 拿到一个一次性 URL；
// 2. 用 `qrURL()` 在**本地**渲染成二维码（内容不出设备 —— 绝不能调第三方二维码服务，
//    那个 URL 谁拿到谁就能登录这个账号）；
// 3. 每 2 秒 `qrcode/poll` 一次；
// 4. 成功时 B 站在**响应头**下发 SESSDATA 等 cookie，宿主的 per-applet cookie 罐自动收下。
//    所以这里没有一行解析 Set-Cookie 的代码 —— 那本来就不该由页面做（多值 Set-Cookie
//    在响应头字典里已被合并成不可靠拆分的逗号串）。
//
// 同一台手机上扫自己屏幕上的码是不行的，所以页面明说：用另一台设备扫，或长按存图后在 B 站 App 里扫。

import React from 'react'
import * as ui from 'aibox/ui'
import { EmptyState, PrimaryButton, Spinner } from './primitives.jsx'
import VideoCard from './VideoCard.jsx'
import { C, RADIUS, SPACE } from './theme.js'
import * as api from '../lib/api.js'
import {
  clearSession, hasSession, imageURL, secretsWritable, toast,
} from '../lib/host.js'
import { formatCount } from '../lib/format.js'

const POLL_MS = 2000

/**
 * `qrURL` 是 `aibox/ui` **1.3.0** 才有的导出，而市场包会被装到**别人的宿主**上。
 *
 * 所以这里必须是 namespace import + 运行时探测：ESM 的具名导入在导出不存在时会在**链接阶段**
 * 直接报错，整个应用连挂载都到不了 —— 一个「二维码画不出来」的降级，会变成「应用打不开」。
 *
 * 回退实现拼的是同一条 `applet://qr/` URL：老宿主没有那条路由，`<img>` 拿到 404，
 * 页面显示的是「二维码没画出来」而不是白屏——这才是正确的降级形状。
 */
const qrURL = typeof ui.qrURL === 'function'
  ? ui.qrURL
  : (content, options) => {
    const bytes = new TextEncoder().encode(String(content || ''))
    let binary = ''
    for (let i = 0; i < bytes.length; i += 1) binary += String.fromCharCode(bytes[i])
    const encoded = btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
    const size = Number((options || {}).size)
    return `applet://localhost/qr/${encoded}${size > 0 ? `?size=${Math.round(size)}` : ''}`
  }

export default function MinePage({ onOpen }) {
  const [phase, setPhase] = React.useState('checking')  // checking | guest | qr | signedIn
  const [user, setUser] = React.useState(null)
  const [qr, setQR] = React.useState(null)              // { url, key }
  const [hint, setHint] = React.useState('')
  const [historyList, setHistory] = React.useState([])
  const [canPersist, setCanPersist] = React.useState(true)
  const pollTimer = React.useRef(null)

  const refresh = React.useCallback(async () => {
    setPhase('checking')
    // 真值是「罐里有没有 cookie」+「nav 认不认」。**不自己记 isLoggedIn 标志**：
    // cookie 会过期而标志不会，漂移后用户会看到「显示已登录但全是未登录数据」。
    const has = await hasSession()
    if (!has) { setPhase('guest'); return }
    try {
      const me = await api.me()
      if (!me) { setPhase('guest'); return }
      setUser(me)
      setPhase('signedIn')
      api.history().then(setHistory).catch(() => setHistory([]))
    } catch {
      setPhase('guest')
    }
  }, [])

  React.useEffect(() => {
    refresh()
    secretsWritable().then(setCanPersist)
    return () => { if (pollTimer.current) clearInterval(pollTimer.current) }
  }, [refresh])

  const startLogin = React.useCallback(async () => {
    try {
      const code = await api.loginQRCode()
      setQR(code)
      setHint('用另一台设备上的哔哩哔哩 App 扫码')
      setPhase('qr')
      if (pollTimer.current) clearInterval(pollTimer.current)
      pollTimer.current = setInterval(async () => {
        try {
          const res = await api.loginPoll(code.key)
          setHint(res.message)
          if (res.status === 'ok') {
            clearInterval(pollTimer.current)
            pollTimer.current = null
            toast('登录成功')
            refresh()
          } else if (res.status === 'expired') {
            clearInterval(pollTimer.current)
            pollTimer.current = null
          }
        } catch { /* 单次轮询失败不中断，下一拍再试 */ }
      }, POLL_MS)
    } catch (err) {
      toast(`拿不到二维码：${err?.message || err}`)
    }
  }, [refresh])

  const signOut = React.useCallback(async () => {
    await clearSession()
    setUser(null)
    setHistory([])
    setPhase('guest')
    toast('已退出登录')
  }, [])

  if (phase === 'checking') return <Spinner label="检查登录状态" />

  if (phase === 'qr' && qr) {
    return (
      <div style={{ padding: SPACE.s5, textAlign: 'center' }}>
        <div style={{
          display: 'inline-block', padding: SPACE.s4,
          background: '#fff', borderRadius: RADIUS.lg,
        }}>
          {/* 白底是必需的：二维码在暗色背景上扫不出来 */}
          <img src={qrURL(qr.url, { size: 220, level: 'M' })} alt="登录二维码"
            style={{ width: 220, height: 220, display: 'block' }} />
        </div>
        <div style={{ marginTop: SPACE.s4, fontSize: 14, color: C.text }}>{hint}</div>
        <div style={{ marginTop: SPACE.s2, fontSize: 12, color: C.faint, lineHeight: 1.6 }}>
          同一台手机没法扫自己的屏幕。<br />
          可以长按二维码存进相册，再用哔哩哔哩 App 从相册识别。
        </div>
        <div style={{ marginTop: SPACE.s5, display: 'flex', gap: SPACE.s2 }}>
          <PrimaryButton onClick={startLogin}>换一个二维码</PrimaryButton>
          <button
            type="button"
            onClick={() => { if (pollTimer.current) clearInterval(pollTimer.current); setPhase('guest') }}
            style={{
              border: `1px solid ${C.line}`, background: 'transparent', color: C.sub,
              borderRadius: RADIUS.md, padding: `0 ${SPACE.s4}px`, fontSize: 14, flexShrink: 0,
            }}
          >
            取消
          </button>
        </div>
      </div>
    )
  }

  if (phase === 'guest') {
    return (
      <div>
        <EmptyState
          title="还没有登录"
          detail={'登录后可以看观看历史、个性化推荐和更高的清晰度。'
            + (canPersist ? '' : '\n注意：这个构建存不住登录态（未签名的模拟器构建），下次启动要重新登录。')}
          actionLabel="扫码登录"
          onAction={startLogin}
        />
      </div>
    )
  }

  return (
    <div className="bl-scroll" style={{ height: '100%', overflowY: 'auto' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s3, padding: SPACE.s4 }}>
        {user?.avatar ? (
          <img src={imageURL(user.avatar, 52)} alt=""
            style={{ width: 52, height: 52, borderRadius: 26, objectFit: 'cover', background: C.surface }} />
        ) : null}
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 16, color: C.text, fontWeight: 500 }}>{user?.name}</div>
          <div style={{ fontSize: 12, color: C.faint, marginTop: 2 }}>
            LV{user?.level} · {formatCount(user?.coins || 0)}硬币
          </div>
        </div>
        <button
          type="button"
          onClick={signOut}
          style={{
            border: `1px solid ${C.line}`, background: 'transparent', color: C.sub,
            borderRadius: RADIUS.md, padding: `6px ${SPACE.s3}px`, fontSize: 13,
          }}
        >
          退出
        </button>
      </div>

      <div style={{ borderTop: `8px solid ${C.surface}`, paddingTop: SPACE.s2 }}>
        <div style={{ padding: `${SPACE.s2}px ${SPACE.s4}px`, fontSize: 13, fontWeight: 600, color: C.sub }}>
          观看历史
        </div>
        {historyList.length === 0 ? (
          <EmptyState title="还没有观看记录" />
        ) : (
          historyList.map((video) => <VideoCard key={video.bvid} video={video} onOpen={onOpen} />)
        )}
      </div>
      <div style={{ height: SPACE.s6 }} />
    </div>
  )
}

