/**
 * 取可播放的 MP4 直链。
 *
 * `fnval: 1` = 老的 MP4 格式，回 `durl[]`（单文件，音视频已合流）。**这是关键选择**：
 * 默认的 `fnval: 4048`（DASH）回的是分离流，AVPlayer 放不了，而小应用又不可能自己合流。
 * 实测未登录能拿到 720P（`format: "mp4720"`），登录后更高。
 *
 * 回 `{ url, quality, format, timelength }`。
 */
export async function playURL(bvid, cid, qn = 80) {
  const data = await get('/x/player/playurl', { bvid, cid, qn, fnval: 1, fourk: 1 })
  const durl = data?.durl || []
  if (!durl.length) throw new Error('这个视频没有可直接播放的地址')
  return {
    url: durl[0].url,
    backup: durl[0].backup_url || [],
    quality: data.quality,
    format: data.format || '',
    // 服务端给的是毫秒
    duration: Math.round((data.timelength || 0) / 1000),
    accepted: (data.accept_description || []).map((label, i) => ({
      label,
      qn: (data.accept_quality || [])[i],
    })).filter((q) => q.qn != null),
  }
}

/** 相关推荐（免签，一次 40 条）。 */
export async function related(bvid) {
  try {
    const data = await get('/x/web-interface/archive/related', { bvid })
    return (Array.isArray(data) ? data : []).map(normalizeVideo).filter(Boolean)
  } catch {
    return []
  }
}

// —— 登录 ——————————————————————————————————————————————

/** 申请登录二维码。回 `{ url, key }`。**走 PASSPORT 域**（见该常量的注释）。 */
export async function loginQRCode() {
  const data = await get('/x/passport-login/web/qrcode/generate', null, PASSPORT)
  if (!data?.url || !data?.qrcode_key) throw new Error('接口没有返回二维码')
  return { url: data.url, key: data.qrcode_key }
}

/**
 * 轮询扫码状态。
 *
 * 关键：登录成功时 B 站在**响应头**里下发 SESSDATA 等 cookie，宿主的 per-applet cookie 罐
 * 会自动收下（`net.fetch` 负责），所以这里**不需要**、也**不应该**自己解析 Set-Cookie。
 * 回 `{ status: 'pending'|'scanned'|'expired'|'ok', message }`。
 */
export async function loginPoll(qrcodeKey) {
  const res = await fetchJSON(
    `${PASSPORT}/x/passport-login/web/qrcode/poll?qrcode_key=${encodeURIComponent(qrcodeKey)}`, HEADERS)
  // 注意是 `data.code` 而不是外层 `code`：外层恒 0（HTTP 层面成功），
  // 真正的扫码状态在 data 里（86101 未扫码 / 86090 已扫待确认 / 86038 失效 / 0 成功）。
  const code = res?.data?.code
  if (code === 0) return { status: 'ok', message: '登录成功' }
  if (code === 86038) return { status: 'expired', message: '二维码已失效' }
  if (code === 86090) return { status: 'scanned', message: '已扫码，请在手机上确认' }
  return { status: 'pending', message: '等待扫码' }
}

/** 当前登录状态。未登录时 nav 回 code=-101。 */
export async function me() {
  const res = await fetchJSON(`${API}/x/web-interface/nav`, HEADERS)
  if (res?.code !== 0 || !res?.data?.isLogin) return null
  return {
    mid: res.data.mid,
    name: res.data.uname || '',
    avatar: normalizeImage(res.data.face || ''),
    level: res.data.level_info?.current_level || 0,
    coins: res.data.money || 0,
  }
}

/** 观看历史（需登录）。 */
export async function history() {
  const data = await get('/x/web-interface/history/cursor', { ps: 20, type: 'archive' })
  return (data?.list || []).map((item) => normalizeVideo({
    ...item,
    bvid: item.history?.bvid,
    cid: item.history?.cid,
    owner: { name: item.author_name, mid: item.author_mid },
  })).filter(Boolean)
}

// 展示层格式化。B 站的数字口径是「万 / 亿」，直接显示原始数字会让人对不上官方 App。

/** 播放量 / 弹幕数：1.2万、3.4亿。一万以下直接显示。 */
export function formatCount(n) {
  const value = Number(n) || 0
  if (value >= 100_000_000) return `${(value / 100_000_000).toFixed(1).replace(/\.0$/, '')}亿`
  if (value >= 10_000) return `${(value / 10_000).toFixed(1).replace(/\.0$/, '')}万`
  return String(value)
}

/** 秒 → "12:34" / "1:02:03"。 */
export function formatDuration(seconds) {
  const total = Math.max(0, Math.round(Number(seconds) || 0))
  const h = Math.floor(total / 3600)
  const m = Math.floor((total % 3600) / 60)
  const s = total % 60
  const pad = (n) => String(n).padStart(2, '0')
  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${m}:${pad(s)}`
}

/** 发布时间：今天显示时刻，今年显示月日，跨年显示年月日。 */
export function formatDate(unixSeconds) {
  const ts = Number(unixSeconds) || 0
  if (!ts) return ''
  const date = new Date(ts * 1000)
  const now = new Date()
  const sameDay = date.toDateString() === now.toDateString()
  if (sameDay) return `${date.getHours()}:${String(date.getMinutes()).padStart(2, '0')}`
  if (date.getFullYear() === now.getFullYear()) return `${date.getMonth() + 1}-${date.getDate()}`
  return `${date.getFullYear()}-${date.getMonth() + 1}-${date.getDate()}`
}

// 宿主能力的薄封装。**所有** `window.aibox` 访问收敛在这里，页面不直接碰桥。
//
// 纪律：每条能力都要有降级路径。宿主变体（Full/Lean）、surface 差异、用户未授权都会让能力缺席，
// 页面据此隐藏入口，而不是留一个点了没反应的按钮。

import { imageURL as uiImageURL } from 'aibox/ui'

const bridge = () => (typeof window !== 'undefined' ? window.aibox : undefined)

// —— 网络 ——————————————————————————————————————————————

/**
 * 取 JSON。用 `responseType: 'json'` 让原生侧解析——省一次 JS 侧 JSON.parse，
 * 也避免大响应在 JS 里再复制一份字符串。
 *
 * `maxBytes` 抬到 2MB：排行榜一次 100 条、搜索一次多组结果，默认 200KB 会被**静默截断**
 * （宿主会回 `truncated: true`，但 JSON 已经断在半截解不出来了）。
 */
/**
 * 从市场安装的应用**权限是归零的**（`AppletMarketInstaller`：「市场包永远带不来授权」），
 * 所以每个用户第一次打开都会撞上这条。宿主给的原文是英文技术信息
 * （`aibox/not-granted: 'net' is not declared — update the applet permissions…`），
 * 直接显示给用户等于让他自己去猜要点哪里。
 *
 * 这条判定**只认前缀**，不认整句：错误文案是宿主的，不该被这里的字符串匹配钉死。
 */
const PERMISSION_HINT = '需要先允许这个小应用联网：在 App 的能力中心里打开它的网络权限，'
  + '然后回到这里重试。（从市场安装的小应用默认不带任何授权。）'

function isPermissionError(message) {
  return /aibox\/(not-granted|denied|not-visible)/.test(String(message || ''))
}

export async function fetchJSON(url, headers = {}) {
  const api = bridge()
  if (!api?.net?.fetch) throw new Error('宿主没有开放网络能力')
  let res
  try {
    res = await api.net.fetch(url, { headers, responseType: 'json', maxBytes: 2 * 1024 * 1024 })
  } catch (cause) {
    const raw = String(cause?.message || cause)
    if (isPermissionError(raw)) {
      const denied = new Error(PERMISSION_HINT)
      denied.permission = true          // 页面据此换成「去授权」而不是「重试」
      throw denied                       // 不标 retryable：重试一万次也还是没授权
    }
    // 传输层失败（超时、断网）值得重试一次。
    const err = new Error(raw)
    err.retryable = true
    throw err
  }
  if (res?.truncated) throw new Error('响应过大被截断')
  if (typeof res?.status === 'number' && (res.status < 200 || res.status >= 300)) {
    const err = new Error(`HTTP ${res.status}`)
    err.retryable = res.status >= 500 || res.status === 429
    throw err
  }
  return res?.body
}

// —— 图片 ——————————————————————————————————————————————

/**
 * 封面/头像的 URL。**必须**走这条：secure CSP 是 `img-src applet: data: blob:`，
 * 裸 `<img src="https://i0.hdslb.com/…">` 会被静默拦成空白。
 * 走 `applet://image/` 还能复用宿主的两级图片缓存（内存 + 磁盘 + 降采样）。
 *
 * `width` 收的是 **CSS 点**，由宿主乘屏幕倍率——JS 侧不要自己乘 dpr，否则缓存键与原生侧对不上。
 */
export function imageURL(url, width) {
  if (!url) return ''
  // 注意：这是 `aibox/ui` 的**纯客户端**字符串拼接函数，不是桥方法——
  // `window.aibox` 上没有 image 命名空间（查过 d.ts），走桥去找它只会拿到 undefined，
  // 表现是所有封面静默变空白。
  return uiImageURL(url, width ? { width } : undefined)
}

// —— 视频播放 ——————————————————————————————————————————

/**
 * 宿主的视频能力状态。
 *
 * **区分三种情况**，因为它们的排查方向完全相反，混成一句「没有视频引擎」会让人查错方向：
 *  · `noBridge`  —— `aibox.video` 命名空间根本不存在。宿主 App 太旧（没有这条桥），
 *                   要重新构建安装宿主，与小应用版本无关。
 *  · `noEngine`  —— 桥在，但 `available:false`：播放器模块没链入这个构建（如 Lean 变体）。
 *  · `ok`        —— 能播。
 */
export async function videoReadiness() {
  const api = bridge()
  if (!api?.video?.availability) {
    return { ok: false, reason: 'noBridge' }
  }
  try {
    const res = await api.video.availability()
    return {
      ok: !!res?.available,
      reason: res?.available ? 'ok' : 'noEngine',
      resolve: !!res?.resolve,
      dash: !!res?.dash,
    }
  } catch (err) {
    return { ok: false, reason: 'noBridge', error: String(err?.message || err) }
  }
}

/** 兼容旧调用点：只关心能不能播。 */
export async function videoAvailable() {
  return (await videoReadiness()).ok
}

/**
 * 打开页面顶部的原生视频区。
 *
 * **必须先开舞台再 play**：舞台开着时播放会内嵌在这块区域里，页面照常竖屏、内容在下面滚；
 * 没开舞台就 play 会接管整屏并转横屏——那对一个「边看边翻简介/选集」的页面是错的。
 */
export async function openStage() {
  const api = bridge()
  if (!api?.video?.stage) return { rendered: false, available: false }
  try {
    // 后台音频默认开：「退出去还能继续听」正是这个应用最常见的用法。
    return await api.video.stage({ aspect: '16:9', backgroundAudio: true })
  } catch {
    return { rendered: false, available: false }
  }
}

/** 收起视频区。**不停止播放** —— 用户可能正想让它转画中画或后台听声。 */
export async function closeStage() {
  fireAndForget(() => bridge()?.video?.dismissStage?.())
}

/** 起播。`resumeFrom` 是续播秒数。舞台开着时宿主会自动内嵌，不必也不该再传 presentation。 */
export async function playVideo({ url, title, resumeFrom = 0 }) {
  const api = bridge()
  if (!api?.video?.play) throw new Error('宿主没有视频播放能力')
  return api.video.play({ url, title, resumeFrom })
}

/** 播放状态快照。`mine` 表示当前播的是不是本应用起的。 */
export async function videoStatus() {
  const api = bridge()
  if (!api?.video?.status) return null
  try {
    return await api.video.status()
  } catch {
    return null
  }
}

/** 订阅播放进度（~2Hz）。回退订函数。 */
export function onVideoProgress(handler) {
  const api = bridge()
  if (!api?.video?.subscribe || !api?.events?.on) return () => {}
  let off = () => {}
  try {
    off = api.events.on('video.progress', handler) || (() => {})
  } catch {
    return () => {}
  }
  fireAndForget(() => api.video.subscribe())
  return () => {
    fireAndForget(() => api.video.unsubscribe?.())
    try { off() } catch { /* 已经退订了 */ }
  }
}

// —— 登录态 ——————————————————————————————————————————

/**
 * 有没有 B 站的会话 cookie。
 *
 * **不要**自己在 storage 里记一个 isLoggedIn 标志——cookie 会过期，标志不会，
 * 两者一旦漂移用户就会看到「显示已登录但接口全是未登录数据」。真值只有一个，就是罐里有没有 cookie。
 */
export async function hasSession() {
  const api = bridge()
  if (!api?.secrets?.hasSession) return false
  try {
    const res = await api.secrets.hasSession({ host: 'bilibili.com' })
    return !!res?.hasSession
  } catch {
    return false
  }
}

/** 登出：丢掉会话 cookie。 */
export async function clearSession() {
  const api = bridge()
  try { await api?.secrets?.clearSession?.({ host: 'bilibili.com' }) } catch { /* 没有就算了 */ }
}

/** Keychain 在这个构建里能不能写（未签名模拟器构建写不了，登录态存不住）。 */
export async function secretsWritable() {
  const api = bridge()
  if (!api?.secrets?.availability) return false
  try {
    const res = await api.secrets.availability()
    return !!res?.available
  } catch {
    return false
  }
}

// —— 本地存储（偏好，不是凭据）——————————————————————————

export async function loadPref(key, fallback = null) {
  const api = bridge()
  if (!api?.storage?.get) return fallback
  try {
    const value = await api.storage.get(key)
    return value == null ? fallback : value
  } catch {
    return fallback
  }
}

export async function savePref(key, value) {
  const api = bridge()
  try { await api?.storage?.set?.(key, value) } catch { /* 偏好存不住不该影响主流程 */ }
}

// —— 交互 ——————————————————————————————————————————————

/**
 * 「发了就不管」的桥调用统一走这里。
 *
 * 桥方法回的是 **Promise**，能力不可用时是 **reject** 而不是 throw ——
 * 同步 `try/catch` 抓不住，于是每一次都变成一条「Unhandled promise rejection」。
 * 无头验收里 `tabs.select` 就是这么冒出来三条 console 错误的。
 */
function fireAndForget(thunk) {
  try {
    const result = thunk()
    if (result && typeof result.catch === 'function') result.catch(() => {})
  } catch { /* 连命名空间都不在 */ }
}

export function haptic(kind = 'light') {
  fireAndForget(() => bridge()?.haptics?.impact?.({ style: kind }))
}

export function toast(message) {
  fireAndForget(() => bridge()?.toast?.show?.({ message }))
}

export async function share(text, url) {
  const api = bridge()
  if (!api?.share?.text) return false
  try {
    // `url` 是独立参数：分享面板据此给出「拷贝链接 / 在浏览器打开」这类链接专属动作，
    // 拼进 text 就只剩一段纯文本了。
    return await api.share.text(url ? { text, url } : { text })
  } catch {
    return false
  }
}

export async function copyText(text) {
  const api = bridge()
  try {
    await api?.clipboard?.write?.({ text })
    return true
  } catch {
    return false
  }
}

/** 用宿主内置浏览器打开（番剧、直播这类本应用没做的页面，交给浏览器而不是留死路）。 */
export async function openInBrowser(url) {
  const api = bridge()
  if (api?.browser?.open) {
    try {
      await api.browser.open({ url, mode: 'inApp' })
      return true
    } catch { /* 落到下面 */ }
  }
  try {
    await api?.open?.url?.({ url })
    return true
  } catch {
    return false
  }
}

// 纯 JS MD5 —— WBI 签名的唯一依赖。
//
// 为什么必须自己写：WebView 的 `crypto.subtle` 只支持 SHA-1/256/384/512，**没有 MD5**
// （Web Crypto 规范就没收它）。而 B 站的 WBI 签名 `w_rid = md5(query + mixin_key)` 只认 MD5。
// 所以这条路上没有平台 API 可用，只能实现一遍。
//
// 实现按 RFC 1321。只处理 ASCII/UTF-8 字符串输入（WBI 的输入是 urlencode 过的 query，必为 ASCII），
// 输出 32 位小写 hex。

const S = [
  7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
  5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
  4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
  6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
]

// K[i] = floor(2^32 × |sin(i+1)|)，RFC 1321 的常量表。写死而不是运行时算：
// 运行时算依赖 Math.sin 的精度，跨引擎不保证逐位一致，而这里错一位签名就全废。
const K = new Uint32Array([
  0xd76aa478, 0xe8c7b756, 0x242070db, 0xc1bdceee, 0xf57c0faf, 0x4787c62a, 0xa8304613, 0xfd469501,
  0x698098d8, 0x8b44f7af, 0xffff5bb1, 0x895cd7be, 0x6b901122, 0xfd987193, 0xa679438e, 0x49b40821,
  0xf61e2562, 0xc040b340, 0x265e5a51, 0xe9b6c7aa, 0xd62f105d, 0x02441453, 0xd8a1e681, 0xe7d3fbc8,
  0x21e1cde6, 0xc33707d6, 0xf4d50d87, 0x455a14ed, 0xa9e3e905, 0xfcefa3f8, 0x676f02d9, 0x8d2a4c8a,
  0xfffa3942, 0x8771f681, 0x6d9d6122, 0xfde5380c, 0xa4beea44, 0x4bdecfa9, 0xf6bb4b60, 0xbebfbc70,
  0x289b7ec6, 0xeaa127fa, 0xd4ef3085, 0x04881d05, 0xd9d4d039, 0xe6db99e5, 0x1fa27cf8, 0xc4ac5665,
  0xf4292244, 0x432aff97, 0xab9423a7, 0xfc93a039, 0x655b59c3, 0x8f0ccc92, 0xffeff47d, 0x85845dd1,
  0x6fa87e4f, 0xfe2ce6e0, 0xa3014314, 0x4e0811a1, 0xf7537e82, 0xbd3af235, 0x2ad7d2bb, 0xeb86d391,
])

const rotl = (x, c) => (x << c) | (x >>> (32 - c))

/** UTF-8 编码成字节数组。WBI 的输入是 ASCII，但不假设——多一行换一类边界 bug 消失。 */
function utf8Bytes(text) {
  if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(text)
  const out = []
  for (let i = 0; i < text.length; i += 1) {
    let c = text.charCodeAt(i)
    if (c < 0x80) out.push(c)
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63))
    else out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63))
  }
  return new Uint8Array(out)
}

/** 32 位小写 hex 的 MD5。 */
export function md5(text) {
  const msg = utf8Bytes(text)
  const bitLen = msg.length * 8
  // padding：0x80 + 若干 0，直到长度 ≡ 56 (mod 64)，末尾 8 字节是小端 64 位比特长度。
  const padded = new Uint8Array(((msg.length + 8) >> 6 << 6) + 64)
  padded.set(msg)
  padded[msg.length] = 0x80
  const view = new DataView(padded.buffer)
  view.setUint32(padded.length - 8, bitLen >>> 0, true)
  view.setUint32(padded.length - 4, Math.floor(bitLen / 0x100000000), true)

  let [a0, b0, c0, d0] = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476]
  const M = new Uint32Array(16)

  for (let chunk = 0; chunk < padded.length; chunk += 64) {
    for (let i = 0; i < 16; i += 1) M[i] = view.getUint32(chunk + i * 4, true)
    let [A, B, C, D] = [a0, b0, c0, d0]
    for (let i = 0; i < 64; i += 1) {
      let F
      let g
      if (i < 16) { F = (B & C) | (~B & D); g = i }
      else if (i < 32) { F = (D & B) | (~D & C); g = (5 * i + 1) % 16 }
      else if (i < 48) { F = B ^ C ^ D; g = (3 * i + 5) % 16 }
      else { F = C ^ (B | ~D); g = (7 * i) % 16 }
      F = (F + A + K[i] + M[g]) | 0
      A = D
      D = C
      C = B
      B = (B + rotl(F, S[i])) | 0
    }
    a0 = (a0 + A) | 0
    b0 = (b0 + B) | 0
    c0 = (c0 + C) | 0
    d0 = (d0 + D) | 0
  }

  // 输出是小端：每个 32 位字按字节倒序输出。
  const hex = (n) => {
    let s = ''
    for (let i = 0; i < 4; i += 1) s += ((n >>> (i * 8)) & 0xff).toString(16).padStart(2, '0')
    return s
  }
  return hex(a0) + hex(b0) + hex(c0) + hex(d0)
}

